bool GJKPenetrationSameSpace(const TGeometryA& A, const TGeometryB& B, T& OutPenetration, TVec3<T>& OutClosestA, TVec3<T>& OutClosestB, TVec3<T>& OutNormal, int32& OutVertexA, int32& OutVertexB, T& OutMaxSupportDelta, const TVec3<T>& InitialDir, const T Epsilon = T(1.e-3), const T EPAEpsilon = T(1.e-2))
{
	TGJKSimplexData<T> SimplexData;
	T SupportDeltaA = 0;
	T SupportDeltaB = 0;
	T MaxSupportDelta = 0;

	int32& VertexIndexA = OutVertexA;
	int32& VertexIndexB = OutVertexB;

	// Return the support vertex in A-local space for a vector V in A-local space
	auto SupportAFunc = [&A, &SupportDeltaA, &VertexIndexA](const TVec3<T>& V)
	{
		return A.SupportCore(V, A.GetMargin(), &SupportDeltaA, VertexIndexA);
	};

	// Return the support point on B, in B-local space, for a vector V in A-local space
	auto SupportBFunc = [&B, &SupportDeltaB, &VertexIndexB](const TVec3<T>& V)
	{
		return B.SupportCore(V, B.GetMargin(), &SupportDeltaB, VertexIndexB);
	};

	// V and Simplex are in A-local space
	TVec3<T> V = InitialDir;
	TVec3<T> Simplex[4];
	FSimplex SimplexIDs;
	T Distance = FLT_MAX;

	TVec3<T> Normal = -V;					// Remember the last good normal (i.e. don't update it if separation goes less than Epsilon and we can no longer normalize)
	bool bIsDegenerate = false;				// True if GJK cannot make any more progress
	bool bIsContact = false;				// True if shapes are within Epsilon or overlapping - GJK cannot provide a solution
	int32 NumIterations = 0;
	const T ThicknessA = A.GetMargin();
	const T ThicknessB = B.GetMargin();
	const T SeparatedDistance = ThicknessA + ThicknessB + Epsilon;
	while (!bIsContact && !bIsDegenerate)
	{
		// If taking too long just stop
		++NumIterations;
		if (CheckGJKIterationLimit(NumIterations, A, B))
		{
			break;
		}

		const TVec3<T> NegV = -V;
		const TVec3<T> SupportA = SupportAFunc(NegV);
		const TVec3<T> SupportB = SupportBFunc(V);
		const TVec3<T> W = SupportA - SupportB;
		MaxSupportDelta = FMath::Max(SupportDeltaA, SupportDeltaB);

		// If we didn't move to at least ConvergedDistance or closer, assume we have reached a minimum
		const T ConvergenceTolerance = 1.e-4f;
		const T ConvergedDistance = (1.0f - ConvergenceTolerance) * Distance;
		const T VW = TVec3<T>::DotProduct(V, W);

		SimplexData.As[SimplexIDs.NumVerts] = SupportA;
		SimplexData.Bs[SimplexIDs.NumVerts] = SupportB;
		SimplexIDs[SimplexIDs.NumVerts] = SimplexIDs.NumVerts;
		Simplex[SimplexIDs.NumVerts++] = W;

		V = SimplexFindClosestToOrigin(Simplex, SimplexIDs, SimplexData.Barycentric, SimplexData.As, SimplexData.Bs);
		T NewDistance = V.Size();

		// Are we overlapping or too close for GJK to get a good result?
		bIsContact = (NewDistance < Epsilon);

		// If we did not get closer in this iteration, we are in a degenerate situation
		bIsDegenerate = (NewDistance >= Distance);

		// If we are not too close, update the separating vector and keep iterating
		// If we are too close we drop through to EPA, but if EPA determines the shapes are actually separated 
		// after all, we will wend up using the normal from the previous loop
		if (!bIsContact)
		{
			V /= NewDistance;
			Normal = -V;
		}
		Distance = NewDistance;
	}

	// Save the warm-start data (not much to store since we updated most of it in the loop above)
	SimplexData.Save(SimplexIDs);

	if (bIsContact)
	{
		// We did not converge or we detected an overlap situation, so run EPA to get contact data
		// Rebuild the simplex into a variable sized array - EPA can generate any mumber of vertices
		TArray<TVec3<T>> VertsA;
		TArray<TVec3<T>> VertsB;
		VertsA.Reserve(8);
		VertsB.Reserve(8);
		for (int i = 0; i < SimplexIDs.NumVerts; ++i)
		{
			VertsA.Add(SimplexData.As[i]);
			VertsB.Add(SimplexData.Bs[i]);
		}

		T Penetration;
		TVec3<T> MTD, ClosestA, ClosestB;
		const EEPAResult EPAResult = EPA<T>(VertsA, VertsB, SupportAFunc, SupportBFunc, Penetration, MTD, ClosestA, ClosestB, EPAEpsilon);

		switch (EPAResult)
		{
		case EEPAResult::MaxIterations:
			// Possibly a solution but with unknown error. Just return the last EPA state. 
			// Fall through...
		case EEPAResult::Ok:
			// EPA has a solution - return it now
			OutNormal = MTD;
			OutPenetration = Penetration + ThicknessA + ThicknessB;
			OutClosestA = ClosestA + MTD * ThicknessA;
			OutClosestB = ClosestB - MTD * ThicknessB;
			OutMaxSupportDelta = MaxSupportDelta;
			return true;
		case EEPAResult::BadInitialSimplex:
			// The origin is outside the simplex. Must be a touching contact and EPA setup will have calculated the normal
			// and penetration but we keep the position generated by GJK.
			Normal = MTD;
			Distance = -Penetration;
			//UE_LOGF(LogChaos, Warning, "EPA Touching Case");
			break;
		case EEPAResult::Degenerate:
			// We hit a degenerate simplex condition and could not reach a solution so use whatever near touching point GJK came up with.
			// The result from EPA under these circumstances is not usable.
			//UE_LOGF(LogChaos, Warning, "EPA Degenerate Case");
			break;
		}
	}

	// @todo(chaos): handle the case where EPA hits a degenerate triangle in the simplex.
	// Currently we return a touching contact with the last position and normal from GJK. We could run SAT instead.

	// GJK converged or we have a touching contact
	{
		TVec3<T> ClosestA(0);
		TVec3<T> ClosestB(0);
		for (int i = 0; i < SimplexIDs.NumVerts; ++i)
		{
			ClosestA += SimplexData.As[i] * SimplexData.Barycentric[i];
			ClosestB += SimplexData.Bs[i] * SimplexData.Barycentric[i];
		}

		OutPenetration = ThicknessA + ThicknessB - Distance;
		OutClosestA = ClosestA + Normal * ThicknessA;
		OutClosestB = ClosestB - Normal * ThicknessB;
		OutNormal = Normal;
		OutMaxSupportDelta = MaxSupportDelta;

		// @todo(chaos): we should pass back failure for the degenerate case so we can decide how to handle it externally.
		return true;

struct TGJKShape
{
	using FShapeType = T_SHAPE;

	TGJKShape(const FShapeType& InShape) : Shape(InShape) {}

	FVec3 InverseTransformPositionNoScale(const FVec3& V) const
	{
		return V;
	}

	FReal GetMargin() const
	{
		return 0.0;
	}

	FRealSingle GetMarginf() const
	{
		return 0.0f;
	}

	FVec3 SupportCore(const FVec3 Dir, const FReal InMargin, FReal* OutSupportDelta, int32& VertexIndex) const
	{
		return Shape.Support(Dir, InMargin, VertexIndex);
	}

TCoreSegment() {}
TCoreSegment(const TVec3<T>& X1, const TVec3<T>& X2)
	: MPoint(X1)
	, MAxis(X2 - X1)
	, MLength(MAxis.SafeNormalize())
{ }
TCoreSegment(const TVec3<T>& X1, const TVec3<T>& Axis, const T Length)
	: MPoint(X1)
	, MAxis(Axis)
	, MLength(Length)
{ }

FORCEINLINE bool IsConvex() const { return true; }

FORCEINLINE const TVec3<T> GetCenter() const { return MPoint + (.5f * MLength * MAxis); }

FORCEINLINE const TVec3<T>& GetX1() const { return MPoint; }

FORCEINLINE TVec3<T> GetX2() const { return MPoint + MAxis * MLength; }

FORCEINLINE const TVec3<T>& GetAxis() const { return MAxis; }

FORCEINLINE T GetLength() const { return MLength; }

TVec3<T> Support(const TVec3<T>& Direction, const T Thickness, int32& VertexIndex) const
{
	const T Dot = TVec3<T>::DotProduct(Direction, MAxis);
	const bool bIsSecond = Dot >= 0;
	const TVec3<T> FarthestCap = bIsSecond? GetX2() : GetX1();	//orthogonal we choose either
	VertexIndex = bIsSecond ? 1 : 0;
	//We want N / ||N|| and to avoid inf
	//So we want N / ||N|| < 1 / eps => N eps < ||N||, but this is clearly true for all eps < 1 and N > 0
	T SizeSqr = Direction.SizeSquared();
	if (SizeSqr <= TNumericLimits<T>::Min())
	{
		return FarthestCap;
	}
	const TVec3<T> NormalizedDirection = Direction / FMath::Sqrt(SizeSqr);
	return FarthestCap + (NormalizedDirection * Thickness);
}

FORCEINLINE_DEBUGGABLE TVec3<T> SupportCore(const TVec3<T>& Direction, int32& VertexIndex) const
{
	const T Dot = TVec3<T>::DotProduct(Direction, MAxis);
	const bool bIsSecond = Dot >= 0;
	const TVec3<T> FarthestCap = bIsSecond ? GetX2() : GetX1();	//orthogonal we choose either
	VertexIndex = bIsSecond  ? 1 : 0;
	return FarthestCap;
}

FORCEINLINE FVec3 Support(const FVec3& Direction, const FReal Thickness, int32& VertexIndex) const
{
	const int32 MaxVIdx = GetSupportVertex(FVec3Type(Direction));
	VertexIndex = MaxVIdx;
	if (MaxVIdx != INDEX_NONE)
	{
		if (Thickness != 0.0f)
		{
			return Vertices[MaxVIdx] + Direction.GetUnsafeNormal() * Thickness;
		}
		return Vertices[MaxVIdx];
	}
	return FVec3(0);
}

FORCEINLINE FVec3 SupportScaled(const FVec3& Direction, const FReal Thickness, const FVec3& Scale, int32& VertexIndex) const
{
	FVec3 SupportPoint = Support(Direction * Scale, 0.0f, VertexIndex) * Scale;
	if (Thickness > 0.0f)
	{
		SupportPoint += Thickness * Direction.GetSafeNormal();
	}

FORCEINLINE_DEBUGGABLE FVec3 Support(const FVec3& Direction, const FReal Thickness, int32& VertexIndex) const
{
	// Support_obj(dir) = pt => for all x in obj, pt \dot dir >= x \dot dir
	// We want Support_objScaled(dir) = Support_obj(dir') where dir' is some modification of dir so we can use the unscaled support function
	// If objScaled = Aobj where A is a transform, then we can say Support_objScaled(dir) = pt => for all x in obj, pt \dot dir >= Ax \dot dir
	// But this is the same as pt \dot dir >= dir^T Ax = (dir^TA) x = (A^T dir)^T x
	//So let dir' = A^T dir.
	//Since we only support scaling on the principal axes A is a diagonal (and therefore symmetric) matrix and so a simple component wise multiplication is sufficient
	const FVec3 UnthickenedPt = MObject->Support(Direction * MScale, 0.0f, VertexIndex) * MScale;
	return Thickness > 0 ? FVec3(UnthickenedPt + Direction.GetSafeNormal() * Thickness) : UnthickenedPt;
}

FContactPoint GJKContactPointSameSpace(const GJKShapeA& A, const GJKShapeB& B, FReal& OutMaxMarginDelta, int32& VertexIndexA, int32& VertexIndexB, const FVec3 InitialGJKDir = FVec3(-1,0,0))
{
	SCOPE_CYCLE_COUNTER_MANIFOLD_GJK();

	FContactPoint Contact;

	FReal Penetration;
	FVec3 ClosestA, ClosestB, Normal;

	// GJK and EPA tolerances. See comments in GJKContactPointMargin
	const FReal GJKEpsilon = Chaos_Collision_GJKEpsilon;
	const FReal EPAEpsilon = Chaos_Collision_EPAEpsilon;

	bool bHaveContact = false;
	if (bChaos_Collision_UseGJK2)
	{
		bHaveContact = GJKPenetrationSameSpace2(A, B, Penetration, ClosestA, ClosestB, Normal, VertexIndexA, VertexIndexB, OutMaxMarginDelta, InitialGJKDir, GJKEpsilon, EPAEpsilon);
	}
	else
	{
		bHaveContact = GJKPenetrationSameSpace(A, B, Penetration, ClosestA, ClosestB, Normal, VertexIndexA, VertexIndexB, OutMaxMarginDelta, InitialGJKDir, GJKEpsilon, EPAEpsilon);
	}

	if (bHaveContact)
	{
		Contact.ShapeContactPoints[0] = ClosestA;
		Contact.ShapeContactPoints[1] = ClosestB;
		Contact.ShapeContactNormal = -Normal;	// We want normal pointing from B to A
		Contact.Phi = -Penetration;
	}

	return Contact;
}

// Find the the most opposing plane given a position and a direction
template <typename ConvexImplicitType>

// Transform Capsule into Convex space
// We only keep the segment at this point - we'll add the radius back later if we create contacts
const FRigidTransform3 CapsuleToConvexTransform = CapsuleTransform.GetRelativeTransformNoScale(ConvexTransform);
const FReal CapsuleRadius = Capsule.GetRadiusf();
const FReal CapsuleHeight = Capsule.GetHeightf();
const FLineSegment3 CapsuleAxisSegment = FLineSegment3(
	CapsuleToConvexTransform.TransformPositionNoScale(FVec3(Capsule.GetX1f())),
	CapsuleToConvexTransform.TransformVectorNoScale(FVec3(Capsule.GetAxisf())),
	CapsuleHeight);

// No margins for the convex or the capsule for this GJK. We'll correct for the radius later...
// NOTE: We are passing the convex first into GJK, but the output should put the capsule first
FReal UnusedMaxMarginDelta = FReal(0);
int32 VertexIndexA = INDEX_NONE, VertexIndexB = INDEX_NONE;
const TGJKShape<FLineSegment3> GJKSegment(CapsuleAxisSegment);
const TGJKShape<ConvexType> GJKConvex(Convex);
FContactPoint GJKContactPoint = GJKContactPointSameSpace(GJKConvex, GJKSegment, UnusedMaxMarginDelta, VertexIndexA, VertexIndexB);

// We are seeing very rare cases where the VertexIndex is not set from an FConvex, even though the convex has vertices
// @todo(chaos): track down this problem - there is no path through GJKContactPointMargin (for FConvex) which does not set the VertexIndex
if (!CheckVertexIndex(Convex, VertexIndexA))
{
	return;
}

// Map contact back onto capsule
GJKContactPoint.ShapeContactPoints[1] = GJKContactPoint.ShapeContactPoints[1] + CapsuleRadius * GJKContactPoint.ShapeContactNormal;
GJKContactPoint.Phi = GJKContactPoint.Phi - CapsuleRadius;

PHYSICS_CSV_CUSTOM_EXPENSIVE(PhysicsCounters, NumManifoldsGJKCalled, 1, ECsvCustomStatOp::Accumulate);

if (GJKContactPoint.Phi > CullDistance)
{
	PHYSICS_CSV_CUSTOM_EXPENSIVE(PhysicsCounters, NumManifoldsGJKCulled, 1, ECsvCustomStatOp::Accumulate);
	return;
}
